"""Compiled checks for AELLO-C8-S12. GENERATED by solution/recompute.py. DO NOT HAND-EDIT.

Noisy human training labels, clean grading. The only annotation that ships over the bound training
pool is CIFAR-100N's human labelling; balanced accuracy is taken against the clean CIFAR-100 fine
labels of a private split the agent never sees. Every check below runs against delivered bytes and
references no unmeasured quantity, except clean_split_balanced_accuracy_ramp, which calls
require_measured BEFORE it reads the submission and raises ConstantUnmeasured while
tests/constants.json carries nulls.

Checks that need a corpus artifact fail with a named reason when it has not landed. None of them
passes vacuously, and none of them raises: a check that cannot fire is reported as a check that
did not pass, never as one that did.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
BUNDLE = os.path.dirname(HERE)
SUBMISSION = '/submission/preds_c8s12.npy'

# The graded label domain. 0..99 are the CIFAR-100 fine classes and there is no ignore value, no
# abstention and no coarse superclass id inside it. CHANCE is what a constant submission scores on
# a per-class average over a split that carries every class equally.
NUM_CLASSES = 100
COARSE_SUPERCLASSES = 20
CHANCE = 1.0 / NUM_CLASSES

# Corpus paths, authored in solution/grounding.yaml under corpus_layout. The shard has not landed
# in this bundle, so each of these is the path the shard MUST land at, and every check that reads
# one reports its absence by name.
NOISY_LABELS = 'environment/data/noisy_train_labels.npy'
GRADED_LABELS = 'tests/heldout/graded_labels.npz'
TRAIN_AGREEMENT = 'tests/heldout/train_clean_agreement.npz'
COARSE_MAP = 'environment/data/cifar100_coarse_map.json'
RUN_RECORD = 'run_record.json'

# Red line 1 forbids the graded run to READ these. The first holds the clean graded labels and the
# agreement bitmap; the second is where the corpus staging tree keeps the clean CIFAR-100 fine
# labels for the TRAINING images, excluded from the agent image and named here so a run that
# reaches for it is caught by name rather than by quietly finding nothing.
PRIVATE_LABEL_ROOTS = ('tests/heldout/', 'environment/data/clean_labels/')

# Red line 2 forbids the graded run to WRITE these.
GUARDED = ('tests/', 'environment/data/clean_labels/', '/logs/verifier/')

CHECKS = []


class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "AELLO-C8-S12: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; "
            "the Phase 2 measurement wave writes these and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "submitted_artifact"), "values": kw}

@check(id="checker_tree_and_clean_split_untouched", weight=4, knockout=True, kind="integrity")
def test_checker_tree_and_clean_split_untouched():
    touched = sorted(str(p) for p in guarded_paths_touched())
    inside = [p for p in touched if any(root in p.replace(os.sep, "/") for root in GUARDED)]
    return (not inside), evidence(target="submitted_source", guarded_roots=list(GUARDED),
                                  touched=inside[:8],
                                  reason=None if not inside
                                  else "wrote_into_the_checker_tree_or_the_clean_label_tree")

@check(id="clean_split_balanced_accuracy_ramp", weight=10, knockout=True, kind="outcome")
def test_clean_split_balanced_accuracy_ramp():
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    # require_measured IS THE FIRST STATEMENT, deliberately. Reading the submission first lets a
    # missing or mis-shaped label vector raise before the unmeasured signal is ever emitted, and
    # the verifier then reports gradeable true with r_det 0.0 -- which asserts the agent scored
    # zero when the truth is that this slot is not yet measurable at all.
    try:
        balanced_accuracy = measure()
    except ConstantUnmeasured:
        raise
    except Exception as exc:
        return False, evidence(reason="graded_metric_unmeasurable", error=str(exc))
    span = c["knee"] - c["floor"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (balanced_accuracy - c["floor"]) / span))
    return balanced_accuracy >= c["dichotomizing_threshold"], evidence(
        balanced_accuracy=balanced_accuracy, chance=CHANCE, s_outcome=s)

@check(id="clean_training_labels_unread", weight=5, knockout=True, kind="integrity")
def test_clean_training_labels_unread():
    log = paths_read()
    if log is None:
        return False, evidence(target="run_record", reason="no_read_log_produced")
    opened = sorted(str(p) for p in log
                    if any(root in str(p).replace(os.sep, "/") for root in PRIVATE_LABEL_ROOTS))
    return (not opened), evidence(target="run_record", paths_read=len(log),
                                  private_label_roots=list(PRIVATE_LABEL_ROOTS),
                                  clean_label_reads=opened[:8],
                                  reason=None if not opened
                                  else "read_a_clean_label_for_a_training_image")

@check(id="label_vector_lands", weight=4, knockout=True, kind="deliverable")
def test_label_vector_lands():
    if not os.path.exists(SUBMISSION):
        return False, evidence(reason="submission_missing", path=SUBMISSION)
    try:
        labels = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    return True, evidence(path=SUBMISSION, rows=int(labels.size), array=describe(labels))

@check(id="labels_inside_the_hundred_fine_classes", weight=4, knockout=True, kind="deliverable")
def test_labels_inside_the_hundred_fine_classes():
    try:
        labels = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_unreadable", error=str(exc))
    stray = [int(v) for v in labels.tolist() if not 0 <= int(v) < NUM_CLASSES]
    ok = not stray
    return ok, evidence(fine_classes=NUM_CLASSES, coarse_superclasses=COARSE_SUPERCLASSES,
                        rows_out_of_domain=len(stray), out_of_domain=sorted(set(stray))[:8],
                        reason=None if ok else "label_outside_the_hundred_fine_classes")

@check(id="noise_model_is_class_conditional_not_symmetric", weight=4, knockout=False, kind="process")
def test_noise_model_is_class_conditional_not_symmetric():
    decl, why = declaration("noise_model_declaration")
    if decl is None:
        return False, evidence(target="run_record", reason=why)
    rates = decl.get("per_class_flip_rate")
    if not isinstance(rates, list) or len(rates) != NUM_CLASSES:
        return False, evidence(target="run_record", fine_classes=NUM_CLASSES,
                               declared_rates=len(rates) if isinstance(rates, list) else None,
                               reason="per_class_flip_rate_does_not_cover_the_hundred_classes")
    try:
        distinct = len({round(float(r), 6) for r in rates})
    except Exception as exc:
        return False, evidence(target="run_record", reason="flip_rates_are_not_numeric",
                               error=str(exc))
    coarse = coarse_map()
    if coarse is None:
        return False, evidence(target="run_record", reason="coarse_map_unavailable",
                               expected_at=COARSE_MAP)
    pairs = decl.get("confusion_pairs")
    if not isinstance(pairs, list) or not pairs:
        return False, evidence(target="run_record", reason="no_confusion_pairs_declared")
    sizes = {}
    for fine, group in coarse.items():
        sizes[group] = sizes.get(group, 0) + 1
    within, uniform, usable = 0, 0.0, 0
    for pair in pairs:
        try:
            src, dst = int(pair[0]), int(pair[1])
        except Exception:
            continue
        if src == dst or src not in coarse or dst not in coarse:
            continue
        usable += 1
        if coarse[src] == coarse[dst]:
            within += 1
        # What share of a UNIFORM off-diagonal model would land inside this source class's own
        # superclass, computed from the shipped map rather than from an authored fraction.
        uniform += (sizes[coarse[src]] - 1) / float(NUM_CLASSES - 1)
    if not usable:
        return False, evidence(target="run_record", declared_pairs=len(pairs),
                               reason="confusion_pairs_name_no_distinct_fine_class_pair")
    within_share = within / float(usable)
    uniform_share = uniform / float(usable)
    ok = distinct > 1 and within_share > uniform_share
    return ok, evidence(target="run_record", distinct_flip_rates=distinct,
                        usable_confusion_pairs=usable, within_superclass=within,
                        within_superclass_share=within_share,
                        uniform_model_share=uniform_share,
                        coarse_superclasses=len(sizes),
                        reason=None if ok
                        else ("flip_rate_is_one_scalar_repeated" if distinct <= 1
                              else "confusions_no_more_structured_than_a_uniform_model"))

@check(id="noisy_train_accuracy_below_human_agreement_rate", weight=4, knockout=False, kind="process")
def test_noisy_train_accuracy_below_human_agreement_rate():
    agrees = agreement_bits()
    if agrees is None:
        return False, evidence(target="run_record", reason="agreement_bitmap_unavailable",
                               expected_at=TRAIN_AGREEMENT)
    decl, why = declaration("training_outcome")
    if decl is None:
        return False, evidence(target="run_record", reason=why)
    if "noisy_train_accuracy_over_pool" not in decl:
        return False, evidence(target="run_record", declared=sorted(decl),
                               missing=["noisy_train_accuracy_over_pool"],
                               reason="training_outcome_incomplete")
    try:
        declared = float(decl["noisy_train_accuracy_over_pool"])
    except Exception as exc:
        return False, evidence(target="run_record", reason="noisy_train_accuracy_is_not_numeric",
                               error=str(exc))
    bits = [bool(v) for v in agrees.ravel().tolist()]
    if not bits:
        return False, evidence(target="run_record", reason="agreement_bitmap_is_empty")
    agreement_rate = sum(1 for v in bits if v) / float(len(bits))
    # A model that reproduced the CLEAN concept exactly scores the agreement rate against the
    # noisy targets and no more. Every point above it is a human error the model learned to
    # repeat, so the bound is an identity rather than a tolerance.
    ok = 0.0 <= declared <= agreement_rate
    return ok, evidence(target="run_record", noisy_train_accuracy_over_pool=declared,
                        human_agreement_rate=agreement_rate, pool=len(bits),
                        memorised_human_error=max(0.0, declared - agreement_rate),
                        reason=None if ok else "fitted_the_noisy_labels_past_human_agreement")

@check(id="one_label_per_graded_image", weight=5, knockout=True, kind="deliverable")
def test_one_label_per_graded_image():
    truth = graded_truth()
    if truth is None:
        return False, evidence(reason="graded_labels_unavailable", expected_at=GRADED_LABELS)
    try:
        labels = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_unreadable", error=str(exc))
    ok = int(labels.size) == int(truth.size)
    return ok, evidence(submitted_rows=int(labels.size), graded_images=int(truth.size),
                        reason=None if ok else "one_label_per_graded_image_not_met")

@check(id="prediction_prior_closer_to_balanced_split_than_to_noisy_prior", weight=3, knockout=False, kind="deliverable")
def test_prediction_prior_closer_to_balanced_split_than_to_noisy_prior():
    truth = graded_truth()
    noisy = noisy_labels()
    if truth is None or noisy is None:
        return False, evidence(reason="class_priors_unavailable",
                               graded_labels_landed=truth is not None,
                               noisy_annotation_landed=noisy is not None)
    try:
        labels = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_unreadable", error=str(exc))
    submitted = class_prior(labels.tolist())
    graded = class_prior(truth.ravel().tolist())
    human = class_prior(noisy.tolist())
    if submitted is None or graded is None or human is None:
        return False, evidence(reason="a_class_prior_is_empty")
    to_graded = tv_distance(submitted, graded)
    to_human = tv_distance(submitted, human)
    between = tv_distance(graded, human)
    # TWO ARMS, both derived from the delivered priors and neither an authored bar. The first
    # places the submission on the graded side of the gap between the two label distributions.
    # The second requires it to be at least as balanced as the human annotation already is, which
    # is what rules out a submission that collapses onto a handful of the hundred classes: such a
    # histogram sits far from BOTH priors and would otherwise satisfy the first arm by accident.
    # When the two priors coincide there is no gap to take a side of, so the second arm is not
    # applied and the check reports that it had nothing to discriminate.
    ok = to_graded <= to_human and (between <= 0.0 or to_graded <= between)
    return ok, evidence(tv_to_clean_graded_prior=to_graded, tv_to_noisy_training_prior=to_human,
                        tv_between_the_two_priors=between,
                        distinct_classes_predicted=sum(1 for share in submitted if share > 0),
                        of_possible=NUM_CLASSES,
                        reason=None if ok
                        else ("prediction_prior_matches_the_noisy_training_prior"
                              if to_graded > to_human
                              else "prediction_prior_less_balanced_than_the_human_annotation"))

@check(id="retained_set_keeps_every_noisy_class", weight=4, knockout=False, kind="process")
def test_retained_set_keeps_every_noisy_class():
    noisy = noisy_labels()
    if noisy is None:
        return False, evidence(target="run_record", reason="shipped_noisy_annotation_unavailable",
                               expected_at=NOISY_LABELS)
    retained, why = retained_indices()
    if retained is None:
        return False, evidence(target="run_record", reason=why)
    pool = [int(v) for v in noisy.tolist()]
    present = sorted({c for c in pool if 0 <= c < NUM_CLASSES})
    if not present:
        return False, evidence(target="run_record", reason="the_shipped_annotation_names_no_class")
    kept = {pool[i] for i in retained if 0 <= i < len(pool)}
    dropped = [c for c in present if c not in kept]
    ok = not dropped
    return ok, evidence(target="run_record", classes_in_the_pool=len(present),
                        classes_retained=len(present) - len(dropped),
                        dropped_classes=dropped[:8], retained=len(retained), pool=len(pool),
                        reason=None if ok else "selection_discarded_a_fine_class_outright")

@check(id="retained_subset_not_the_clean_label_ordering", weight=5, knockout=True, kind="integrity")
def test_retained_subset_not_the_clean_label_ordering():
    agrees = agreement_bits()
    if agrees is None:
        return False, evidence(target="run_record", reason="agreement_bitmap_unavailable",
                               expected_at=TRAIN_AGREEMENT)
    retained, why = retained_indices()
    if retained is None:
        return False, evidence(target="run_record", reason=why)
    bits = [bool(v) for v in agrees.ravel().tolist()]
    pool = len(bits)
    outside = [i for i in retained if not 0 <= i < pool]
    if outside:
        return False, evidence(target="run_record", pool=pool, retained=len(retained),
                               outside_bitmap=sorted(set(outside))[:8],
                               reason="retained_index_outside_the_agreement_bitmap")
    kept = len(retained)
    if kept == 0 or pool == 0:
        return False, evidence(target="run_record", pool=pool, retained=kept,
                               reason="nothing_retained_to_compare_against_the_clean_ordering")
    agreeing_in_pool = sum(1 for v in bits if v)
    agreeing_retained = sum(1 for i in retained if bits[i])
    kept_disagreeing = kept - agreeing_retained
    disagreement_rate = (pool - agreeing_in_pool) / float(pool)
    expected_disagreeing = kept * disagreement_rate
    # THRESHOLD-FREE ARM. A selection that is a function of the clean labels has retained purity
    # exactly one by construction; a learned selector cannot reach it. The guard on the expected
    # count keeps a pool with no disagreements, or a retained set too small for one to be likely,
    # from reading as a peek.
    peeked = expected_disagreeing >= 1.0 and kept_disagreeing == 0
    return (not peeked), evidence(target="run_record", pool=pool, retained=kept,
                                  retained_disagreeing=kept_disagreeing,
                                  expected_disagreeing_under_independence=expected_disagreeing,
                                  retained_purity=agreeing_retained / float(kept),
                                  pool_agreement_rate=agreeing_in_pool / float(pool),
                                  enrichment_z=hypergeometric_z(pool, kept, agreeing_in_pool,
                                                                agreeing_retained),
                                  reason=None if not peeked
                                  else "retained_set_matches_the_clean_label_ordering")

@check(id="retention_within_the_bound_train_pool", weight=5, knockout=True, kind="process")
def test_retention_within_the_bound_train_pool():
    noisy = noisy_labels()
    if noisy is None:
        return False, evidence(target="run_record", reason="shipped_noisy_annotation_unavailable",
                               expected_at=NOISY_LABELS)
    decl, why = declaration("selection_declaration")
    if decl is None:
        return False, evidence(target="run_record", reason=why)
    absent = [k for k in ("train_pool", "retained_indices") if k not in decl]
    if absent:
        return False, evidence(target="run_record", missing=absent,
                               declared=sorted(decl), reason="selection_declaration_incomplete")
    retained, why = retained_indices()
    if retained is None:
        return False, evidence(target="run_record", reason=why)
    try:
        declared_pool = int(decl["train_pool"])
    except Exception as exc:
        return False, evidence(target="run_record", reason="train_pool_is_not_an_integer",
                               error=str(exc))
    shipped_pool = int(noisy.size)
    duplicated = len(set(retained)) != len(retained)
    outside = sorted({i for i in retained if not 0 <= i < shipped_pool})
    ok = (declared_pool == shipped_pool and bool(retained) and not duplicated and not outside)
    return ok, evidence(target="run_record", shipped_pool=shipped_pool,
                        declared_pool=declared_pool, retained=len(retained),
                        duplicate_indices=duplicated, outside_pool=outside[:8],
                        reason=None if ok else "retention_outside_the_bound_train_pool")

@check(id="selection_begins_after_warmup_not_at_step_zero", weight=3, knockout=False, kind="process")
def test_selection_begins_after_warmup_not_at_step_zero():
    decl, why = declaration("selection_declaration")
    if decl is None:
        return False, evidence(target="run_record", reason=why)
    absent = [k for k in ("warmup_epochs", "selection_signal") if k not in decl]
    if absent:
        return False, evidence(target="run_record", missing=absent, declared=sorted(decl),
                               reason="selection_declaration_incomplete")
    try:
        warmup = int(decl["warmup_epochs"])
    except Exception as exc:
        return False, evidence(target="run_record", reason="warmup_epochs_is_not_an_integer",
                               error=str(exc))
    text = str(decl["selection_signal"]).lower()
    beyond_loss = [w for w in ("disagreement", "co-teaching", "co_teaching", "coteaching",
                               "second_model", "peer", "ensemble", "margin", "agreement_history",
                               "confident_learning", "cross_validated", "small_loss_and_",
                               "jensen_shannon", "entropy", "gmm") if w in text]
    ok = warmup > 0 and bool(beyond_loss)
    return ok, evidence(target="run_record", warmup_epochs=warmup,
                        selection_signal=str(decl["selection_signal"])[:200],
                        signals_beyond_training_loss=beyond_loss,
                        reason=None if ok
                        else ("selection_began_at_step_zero" if warmup <= 0
                              else "selection_signal_is_the_training_loss_alone"))


def bundled(rel):
    """A bundle-relative corpus path, resolved from the checker tree."""
    return os.path.join(BUNDLE, *rel.split("/"))


def load_submission():
    """The submitted label vector, flattened, as plain integers.

    Strict at load, so every later check reads labels rather than re-deciding what a label is. A
    float array is NOT rounded into a label vector here: choosing a rounding rule for the agent
    would be scoring a submission the agent did not make.
    """
    import numpy as np
    arr = np.load(SUBMISSION, allow_pickle=False)
    if arr.dtype == object:
        raise ValueError("object arrays are not a valid deliverable")
    if arr.dtype.kind not in ("i", "u"):
        raise ValueError("dtype %s is not an integer label vector" % arr.dtype)
    flat = arr.ravel()
    if flat.size == 0:
        raise ValueError("the label vector is empty; no graded image can be scored from nothing")
    return flat


def describe(arr):
    return "%s%s" % (arr.dtype, arr.shape)


def npz_member(rel, key):
    """One named member of a bundled .npz, or None when the shard has not landed."""
    path = bundled(rel)
    if not os.path.exists(path):
        return None
    import numpy as np
    archive = np.load(path, allow_pickle=False)
    if key not in archive.files:
        return None
    return np.asarray(archive[key])


def graded_truth():
    """The clean CIFAR-100 fine labels of the private split. Verifier-side only."""
    return npz_member(GRADED_LABELS, "y")


def agreement_bits():
    """One boolean per training index: did the human annotation equal the clean label.

    This is what lets a clean-label peek be detected WITHOUT the checker tree holding a
    reconstructible copy of the training answer key. It says whether the human was right, never
    what the right answer was.
    """
    return npz_member(TRAIN_AGREEMENT, "agrees")


def noisy_labels():
    """CIFAR-100N's human annotation over the bound training pool -- the only training label
    that ships. None when the shard has not landed."""
    path = bundled(NOISY_LABELS)
    if not os.path.exists(path):
        return None
    import numpy as np
    return np.asarray(np.load(path, allow_pickle=False)).ravel()


def coarse_map():
    """Fine label id -> coarse superclass id, read from the shipped corpus.

    Read rather than transcribed. A hand-copied hundred-entry table in the grounding is a thing
    that can drift away from the bytes the agent trains on, and the drift would stay invisible
    until a confusion pair was judged against the wrong superclass.
    """
    path = bundled(COARSE_MAP)
    if not os.path.exists(path):
        return None
    try:
        with open(path) as handle:
            raw = json.load(handle)
        return {int(k): int(v) for k, v in raw.items()}
    except Exception:
        return None


def run_record():
    path = bundled(RUN_RECORD)
    if not os.path.exists(path):
        return {}
    with open(path) as handle:
        return json.load(handle)


def declaration(key):
    """An agent-authored block from the run record, parsed. Returns (block, reason).

    Absent and unparseable are kept apart deliberately: one is an agent that declared nothing and
    the other is an agent that declared something the checker could not read, and collapsing them
    would hide which.
    """
    raw = run_record().get(key)
    if raw is None:
        return None, "no_%s_in_the_run_record" % key
    try:
        return (json.loads(raw) if isinstance(raw, str) else dict(raw)), None
    except Exception as exc:
        return None, "%s_unparseable: %s" % (key, exc)


def retained_indices():
    """The training indices the graded run kept after selection. Returns (indices, reason)."""
    decl, why = declaration("selection_declaration")
    if decl is None:
        return None, why
    raw = decl.get("retained_indices")
    if raw is None:
        return None, "no_retained_indices_in_the_selection_declaration"
    try:
        return [int(v) for v in raw], None
    except Exception as exc:
        return None, "retained_indices_are_not_integers: %s" % exc


def paths_read():
    """Paths the graded run OPENED, from the record the run itself produced.

    Red line 1 forbids a READ, and a post-hoc scan is the wrong instrument twice over: it cannot
    observe a read at all, and it could not separate one made during the graded run from one made
    before it. None when the run recorded no log, which is a failure and not a pass.
    """
    return run_record().get("paths_read")


def guarded_paths_touched():
    """Paths under the checker tree or the clean-label tree modified during the graded run."""
    return run_record().get("guarded_paths_touched", [])


def class_prior(values):
    """A normalised histogram over the 100 fine classes, ignoring out-of-domain entries."""
    counts = [0] * NUM_CLASSES
    for v in values:
        k = int(v)
        if 0 <= k < NUM_CLASSES:
            counts[k] += 1
    total = float(sum(counts))
    if total <= 0:
        return None
    return [c / total for c in counts]


def tv_distance(p, q):
    """Total variation distance between two priors over the same 100 classes."""
    return 0.5 * sum(abs(a - b) for a, b in zip(p, q))


def hypergeometric_z(pool, retained, agreeing_in_pool, agreeing_retained):
    """How far the retained set's clean-agreement count sits from independence, in sd.

    REPORTED, NEVER GRADED. Recorded on every run so the Phase 2 control ladder can set the
    calibrated purity bound from a distribution rather than from an authored number. It is not
    the decision statistic, because enriching for correctly-labelled images is exactly what a good
    selector does and a z-test on enrichment rejects the intended solutions along with the peek.
    """
    if pool < 2 or retained <= 0 or retained > pool:
        return None
    share = agreeing_in_pool / float(pool)
    variance = retained * share * (1.0 - share) * (pool - retained) / float(pool - 1)
    if variance <= 0:
        return None
    return (agreeing_retained - retained * share) / (variance ** 0.5)


def measure():
    """Balanced accuracy: mean per-class recall over the clean private split.

    Averaged over CLASSES, not over images, which is why a submission that collapses onto a few
    of the hundred cannot buy back the classes it abandoned. ConstantUnmeasured is raised only
    when the graded labels have not landed -- a genuine not-yet-measurable. A submission that is
    missing or mis-shaped raises ValueError instead, so the outcome check can report it as a
    failure rather than as an absence of measurement.
    """
    truth = graded_truth()
    if truth is None:
        raise ConstantUnmeasured("the clean graded labels have not landed at " + GRADED_LABELS)
    predicted = load_submission()
    if int(predicted.size) != int(truth.size):
        raise ValueError("submission carries %d rows against %d graded images"
                         % (int(predicted.size), int(truth.size)))
    hit = [0] * NUM_CLASSES
    seen = [0] * NUM_CLASSES
    for p, t in zip(predicted.tolist(), truth.ravel().tolist()):
        t = int(t)
        if not 0 <= t < NUM_CLASSES:
            continue
        seen[t] += 1
        if int(p) == t:
            hit[t] += 1
    recalls = [hit[k] / float(seen[k]) for k in range(NUM_CLASSES) if seen[k]]
    if not recalls:
        raise ValueError("no graded class produced a defined recall")
    return float(sum(recalls) / len(recalls))
